function turnRight() {
    turnLeft();
    turnLeft();
    turnLeft();
}

// (Extra) one possible approach: lay a row of alternating beepers, then
// reposition to the next row and shift the starting offset by one.
function beeperRowStartingWithBeeper() {
    putBeeper();
    move();
    move();
    putBeeper();
    move();
    move();
    putBeeper();
}

function beeperRowStartingEmpty() {
    move();
    putBeeper();
    move();
    move();
    putBeeper();
}
